use std::{collections::BTreeMap,fs::{self,File,OpenOptions},io::Write,path::{Path,PathBuf},sync::atomic::{AtomicU64,Ordering}};
use crate::{blob_not_found_error::BlobNotFoundError,reference::{BlobRef,BlobRefError}};
static COUNTER:AtomicU64=AtomicU64::new(0);
enum Backend{Memory(BTreeMap<BlobRef,Vec<u8>>),Fs(PathBuf)}
pub struct BlobStore{backend:Backend}
#[derive(Debug)]pub enum BlobStoreError{NotFound(BlobNotFoundError),InvalidReference(BlobRefError),Corrupt(String),Io(String)}
impl std::fmt::Display for BlobStoreError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self{Self::NotFound(e)=>write!(f,"{e}"),Self::InvalidReference(e)=>write!(f,"invalid blob reference: {e}"),Self::Corrupt(e)=>write!(f,"corrupt blob: {e}"),Self::Io(e)=>write!(f,"blob store I/O error: {e}")}}}
impl std::error::Error for BlobStoreError{}
impl Default for BlobStore{fn default()->Self{Self::in_memory()}}
impl BlobStore{
 pub fn in_memory()->Self{Self{backend:Backend::Memory(BTreeMap::new())}}
 pub fn open(root:impl Into<PathBuf>)->Result<Self,BlobStoreError>{let root=root.into();fs::create_dir_all(&root).map_err(|e|BlobStoreError::Io(format!("create {}: {e}",root.display())))?;sync_dir(&root)?;Ok(Self{backend:Backend::Fs(root)})}
 pub fn put(&mut self,bytes:Vec<u8>)->Result<BlobRef,BlobStoreError>{let r=BlobRef::from_content(&bytes);self.put_with_reference(&r,&bytes)?;Ok(r)}
 pub fn put_with_reference(&mut self,r:&BlobRef,bytes:&[u8])->Result<(),BlobStoreError>{r.verify(bytes).map_err(BlobStoreError::InvalidReference)?;match &mut self.backend{Backend::Memory(m)=>{m.insert(r.clone(),bytes.to_vec());Ok(())},Backend::Fs(root)=>write_atomic(root,r,bytes)}}
 pub fn get(&self,r:&BlobRef)->Result<Vec<u8>,BlobStoreError>{let bytes=match &self.backend{Backend::Memory(m)=>m.get(r).cloned().ok_or_else(||BlobStoreError::NotFound(BlobNotFoundError(r.as_str().into())))?,Backend::Fs(root)=>match fs::read(root.join(r.as_str())){Ok(b)=>b,Err(e)if e.kind()==std::io::ErrorKind::NotFound=>return Err(BlobStoreError::NotFound(BlobNotFoundError(r.as_str().into()))),Err(e)=>return Err(BlobStoreError::Io(e.to_string()))}};r.verify(&bytes).map_err(|e|BlobStoreError::Corrupt(format!("{} ({e})",r.as_str())))?;Ok(bytes)}
 pub fn get_optional(&self,r:&BlobRef)->Result<Option<Vec<u8>>,BlobStoreError>{match self.get(r){Ok(b)=>Ok(Some(b)),Err(BlobStoreError::NotFound(_))=>Ok(None),Err(e)=>Err(e)}}
 pub fn is_blob_durable(&self,r:&BlobRef)->Option<bool>{match &self.backend{Backend::Memory(_)=>None,Backend::Fs(root)=>Some(root.join(r.as_str()).is_file())}}
 pub fn flush(&self)->Result<(),BlobStoreError>{match &self.backend{Backend::Memory(_)=>Ok(()),Backend::Fs(root)=>sync_dir(root)}}
}
fn write_atomic(root:&Path,r:&BlobRef,bytes:&[u8])->Result<(),BlobStoreError>{let dst=root.join(r.as_str());match fs::read(&dst){Ok(old)if old==bytes&&r.verify(&old).is_ok()=>return sync_dir(root),Ok(_)=>{},Err(e)if e.kind()==std::io::ErrorKind::NotFound=>{},Err(e)=>return Err(BlobStoreError::Io(e.to_string()))}let tmp=root.join(format!(".{}.tmp-{}-{}",r.as_str(),std::process::id(),COUNTER.fetch_add(1,Ordering::Relaxed)));let result=(||{let mut f=OpenOptions::new().write(true).create_new(true).open(&tmp).map_err(|e|BlobStoreError::Io(e.to_string()))?;f.write_all(bytes).map_err(|e|BlobStoreError::Io(e.to_string()))?;f.sync_all().map_err(|e|BlobStoreError::Io(e.to_string()))?;drop(f);fs::rename(&tmp,&dst).map_err(|e|BlobStoreError::Io(e.to_string()))?;sync_dir(root)})();if result.is_err(){let _=fs::remove_file(&tmp); } result}
fn sync_dir(path:&Path)->Result<(),BlobStoreError>{File::open(path).and_then(|f|f.sync_all()).map_err(|e|BlobStoreError::Io(format!("fsync {}: {e}",path.display())))}
#[cfg(test)]mod tests{use super::*;#[test]fn memory_missing_and_digest_validation(){let mut s=BlobStore::default();let r=s.put(b"data".to_vec()).unwrap();assert_eq!(s.get(&r).unwrap(),b"data");assert!(matches!(s.get(&BlobRef::from_content(b"missing")),Err(BlobStoreError::NotFound(_))));assert!(s.put_with_reference(&r,b"wrong").is_err())}#[test]fn durable_file_store_detects_corruption(){let d=tempfile::tempdir().unwrap();let r={let mut s=BlobStore::open(d.path()).unwrap();s.put(b"durable".to_vec()).unwrap()};let s=BlobStore::open(d.path()).unwrap();assert_eq!(s.get(&r).unwrap(),b"durable");fs::write(d.path().join(r.as_str()),b"bad").unwrap();assert!(matches!(s.get(&r),Err(BlobStoreError::Corrupt(_))))}}
